class MainActivity:Activity(){
 private val cream=Color.rgb(247,245,240);private val ink=Color.rgb(40,36,43);private val muted=Color.rgb(124,116,128);private val purple=Color.rgb(113,61,232);private val lavender=Color.rgb(235,227,248)
 private val prefs by lazy{getSharedPreferences("plyt-private",Context.MODE_PRIVATE)}
 private val worker=Executors.newSingleThreadExecutor();private var busy=false
 private var user:JSONObject?=null;private var spaces=JSONArray();private var requests=JSONArray();private var favorites=mutableSetOf<Int>();private var page="explore";private var query="";private var category="전체"
 private lateinit var root:LinearLayout;private lateinit var content:LinearLayout;private lateinit var cards:LinearLayout
 private val statuses=mapOf("pending" to "요청 접수","proposed" to "변경 제안 도착","accepted_a" to "기존 예약자 수락","accepted_b" to "업체 확인 대기","confirmed" to "업체 확인 완료","cancelled" to "요청 취소","declined" to "제안 거절")
 private fun dp(n:Int)=(n*resources.displayMetrics.density).toInt()
 private fun base()=prefs.getString("base",if(BuildConfig.DEBUG)"http://10.0.2.2:8080" else "")!!.trimEnd('/')
 private fun token()=prefs.getString("token","")!!
 override fun onCreate(saved:Bundle?){super.onCreate(saved);shell();refresh()}
 override fun onDestroy(){worker.shutdownNow();super.onDestroy()}
 private fun toast(s:String){Toast.makeText(this,s,Toast.LENGTH_LONG).show()}
 private fun shape(color:Int,r:Int=16,border:Boolean=false)=GradientDrawable().apply{setColor(color);cornerRadius=dp(r).toFloat();if(border)setStroke(dp(1),0xffe1dbe5.toInt())}
 private fun col(p:Int=0)=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(p),dp(p),dp(p),dp(p))}
 private fun row()=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL}
 private fun text(s:String,size:Float=14f,color:Int=ink,bold:Boolean=false)=TextView(this).apply{text=s;textSize=size;setTextColor(color);if(bold)typeface=Typeface.create("sans-serif-medium",Typeface.NORMAL);setLineSpacing(dp(3).toFloat(),1f)}
 private fun LinearLayout.words(s:String,size:Float=14f,color:Int=ink,bold:Boolean=false){addView(text(s,size,color,bold))}
 private fun LinearLayout.gap(n:Int=12){addView(View(this@MainActivity),LinearLayout.LayoutParams(1,dp(n)))}
 private fun button(s:String,primary:Boolean=true,fn:()->Unit)=Button(this).apply{text=s;isAllCaps=false;textSize=13f;setTextColor(if(primary)Color.WHITE else purple);background=shape(if(primary)purple else lavender,12);minHeight=dp(46);setPadding(dp(12),dp(6),dp(12),dp(6));layoutParams=LinearLayout.LayoutParams(-1,dp(48)).apply{topMargin=dp(8)};setOnClickListener{fn()}}
 private fun edit(h:String,value:String="",type:Int=1)=EditText(this).apply{hint=h;setText(value);inputType=type;textSize=14f;setTextColor(ink);setHintTextColor(muted);background=shape(Color.WHITE,12,true);setPadding(dp(14),dp(10),dp(14),dp(10));minHeight=dp(48);maxLines=1;layoutParams=LinearLayout.LayoutParams(-1,-2).apply{topMargin=dp(8)}}
 private class ApiError(val code:Int,message:String):Exception(message)
 private fun api(path:String,method:String="GET",body:JSONObject?=null):JSONObject{
  if(base().isBlank())throw Exception("설정에서 HTTPS 서버 주소를 입력해주세요.")
  val url=URL(base()+path);if(url.protocol!="https"&&!(BuildConfig.DEBUG&&url.protocol=="http"))throw Exception("HTTPS 서버 주소가 필요해요.")
  val c=url.openConnection() as HttpURLConnection
  try{c.requestMethod=method;c.connectTimeout=10000;c.readTimeout=15000;c.setRequestProperty("Accept","application/json");if(token().isNotBlank())c.setRequestProperty("Authorization","Bearer "+token());if(body!=null){c.doOutput=true;c.setRequestProperty("Content-Type","application/json; charset=utf-8");c.outputStream.use{it.write(body.toString().toByteArray(Charsets.UTF_8))}}
   val code=c.responseCode;val stream=if(code in 200..299)c.inputStream else c.errorStream;val raw=stream?.bufferedReader(Charsets.UTF_8)?.use{it.readText()}?:"{}";val result=try{JSONObject(raw)}catch(e:Exception){throw Exception("API 서버 응답을 읽지 못했어요. 서버 주소를 확인해주세요.")};if(code !in 200..299)throw ApiError(code,result.optString("error","요청을 처리하지 못했어요."));return result
  }finally{c.disconnect()}
 }
 private fun task(work:()->JSONObject,done:(JSONObject)->Unit){if(busy){toast("처리 중이에요. 잠시 기다려주세요.");return};busy=true;worker.execute{try{val result=work();runOnUiThread{busy=false;if(!isDestroyed)done(result)}}catch(e:Exception){runOnUiThread{busy=false;if(!isDestroyed){if(e is ApiError&&e.code==401){prefs.edit().remove("token").apply();user=null};toast(e.message?:"서버에 연결하지 못했어요.")}}}}}
 private fun refresh(){task({val j=api("/api/spaces");if(token().isNotBlank()){try{j.put("me",api("/api/me"));j.put("favorites",api("/api/favorites").getJSONArray("ids"));j.put("requests",api("/api/requests").getJSONArray("requests"))}catch(e:ApiError){if(e.code==401)j.put("expired",true)else throw e}};j}){j->spaces=j.getJSONArray("spaces");if(j.optBoolean("expired")){prefs.edit().remove("token").apply();user=null;favorites.clear();requests=JSONArray();toast("로그인이 만료됐어요.")}else{user=j.optJSONObject("me");requests=j.optJSONArray("requests")?:JSONArray();favorites.clear();j.optJSONArray("favorites")?.let{a->for(i in 0 until a.length())favorites.add(a.getInt(i))}};shell()}}
 private fun shell(){root=col();root.setBackgroundColor(cream);setContentView(root);root.setOnApplyWindowInsetsListener{v,ins->if(Build.VERSION.SDK_INT>=30){val bars=ins.getInsets(WindowInsets.Type.systemBars());v.setPadding(bars.left,bars.top,bars.right,bars.bottom)}else{v.setPadding(ins.systemWindowInsetLeft,ins.systemWindowInsetTop,ins.systemWindowInsetRight,ins.systemWindowInsetBottom)};ins}
  val top=row().apply{setPadding(dp(22),dp(15),dp(18),dp(12))};top.addView(text("✳ PLYT",29f,purple,true),LinearLayout.LayoutParams(0,-2,1f));top.addView(text(if(user==null)"로그인 ↗"else user!!.optString("name")+" 님",13f,ink,true).apply{setPadding(dp(8),dp(10),0,dp(10));setOnClickListener{if(user==null)auth()else{page="account";shell()}}});root.addView(top)
  val scroll=ScrollView(this).apply{isFillViewport=true};content=col(22);scroll.addView(content);root.addView(scroll,LinearLayout.LayoutParams(-1,0,1f));val nav=row().apply{setBackgroundColor(Color.WHITE);setPadding(dp(6),dp(6),dp(6),dp(6))}
  listOf("explore" to "⌂  둘러보기","saved" to "♡  저장","requests" to if(user?.optString("role")=="owner")"▤  운영"else"▤  내 요청","account" to "⚙  설정").forEach{(key,title)->nav.addView(text(title,12f,if(page==key)purple else muted,page==key).apply{gravity=Gravity.CENTER;setPadding(0,dp(14),0,dp(14));setOnClickListener{page=key;shell()}},LinearLayout.LayoutParams(0,-2,1f))};root.addView(nav);render()
 }
 private fun render(){content.removeAllViews();when(page){"explore","saved"->catalog();"requests"->requestList();else->account()}}
 private fun catalog(){if(page=="explore"){content.words("MAKE ROOM FOR YOUR TIME",10f,purple,true);content.gap();content.words("좋은 시간은,\n이어지니까.",34f,ink,true);content.gap(10);content.words("마감된 시간에도 새로운 가능성.\n당신을 위한 공간을 찾아보세요.",14f,muted);content.gap(18);content.addView(col(15).apply{background=shape(lavender,14);words("✳  작은 유연함이 만드는 다음 기회",13f,purple,true);gap(6);words("희망 시간 요청 → 양측 수락 → 업체 확인",11f,muted)});content.gap(18)}else{content.words("저장한 공간",28f,ink,true);content.gap(8);content.words("마음에 남은 공간을 다시 만나보세요.",13f,muted);content.gap()}
  val q=edit("공간 이름이나 지역으로 검색",query);content.addView(q);q.addTextChangedListener(object:TextWatcher{override fun beforeTextChanged(s:CharSequence?,st:Int,c:Int,a:Int){};override fun onTextChanged(s:CharSequence?,st:Int,b:Int,c:Int){query=s.toString();renderCards()};override fun afterTextChanged(s:Editable?){} });val filters=row();listOf("전체","촬영 스튜디오","연습실").forEach{item->val b=button(item,false){category=item;render()};b.setTextColor(if(category==item)Color.WHITE else muted);b.background=shape(if(category==item)ink else Color.WHITE,24);filters.addView(b,LinearLayout.LayoutParams(0,dp(43),1f).apply{setMargins(dp(2),dp(12),dp(2),dp(12))})};content.addView(filters);content.words("등록 예시 공간 · 실제 입점 및 가용 시간 확인 필요",10f,muted);content.gap();cards=col();content.addView(cards);renderCards()
 }
 private fun renderCards(){if(!::cards.isInitialized)return;cards.removeAllViews();var count=0;for(i in 0 until spaces.length()){val s=spaces.getJSONObject(i);val id=s.getInt("id");if(page=="saved"&&!favorites.contains(id))continue;if(category!="전체"&&category!=s.getString("category"))continue;if(query.isNotBlank()&&!(s.getString("name")+s.getString("area")).contains(query,true))continue;count++;val card=col().apply{background=shape(Color.WHITE,18,true);clipToOutline=true};card.addView(SpaceArt(this,id),LinearLayout.LayoutParams(-1,dp(160)));val d=col(18);d.words(s.getString("area")+"   ·   "+s.getString("category"),11f,muted);d.gap(5);d.words(s.getString("name"),21f,ink,true);d.gap(5);d.words(s.getString("description"),12f,muted);d.gap(14);val price=row();price.addView(text(money(s.getInt("price"))+" / 2시간",15f,ink,true),LinearLayout.LayoutParams(0,-2,1f));price.addView(button(if(favorites.contains(id))"♥ 저장됨"else"♡ 저장",false){if(user==null)auth()else task({api("/api/favorites","POST",JSONObject().put("spaceId",id).put("saved",!favorites.contains(id)))}){if(favorites.contains(id))favorites.remove(id)else favorites.add(id);renderCards()}},LinearLayout.LayoutParams(dp(100),dp(43)));d.addView(price);d.addView(button("희망 시간 요청하기  ↗"){if(user==null)auth()else createRequest(s)});card.addView(d);cards.addView(card);cards.gap(18)};if(count==0){cards.gap(28);cards.words(if(page=="saved")"아직 저장한 공간이 없어요.\n둘러보기에서 ♡를 눌러보세요."else if(spaces.length()==0)"서버 연결 후 공간을 불러올 수 있어요.\n설정에서 서버 주소를 확인해주세요."else"검색 결과가 없어요. 다른 이름을 입력해주세요.",14f,muted);cards.addView(button("새로고침",false){refresh()})}}
 private fun money(n:Int)=String.format("%,d원",n)
 private fun requestList(){content.words(if(user?.optString("role")=="owner")"오늘의 운영"else"내 시간 요청",28f,ink,true);content.gap(8);content.words("요청부터 양측 수락, 업체 확인까지 한눈에.",13f,muted);content.addView(button("진행 상황 새로고침",false){refresh()});content.gap(16);if(user==null){content.words("로그인하고 요청과 도착한 제안을 확인하세요.",14f,muted);content.addView(button("로그인 / 회원가입"){auth()});return};if(requests.length()==0){content.words("아직 진행 중인 요청이 없어요.\n원하는 공간에서 희망 시간을 남겨보세요.",14f,muted);return}
  for(i in 0 until requests.length()){val r=requests.getJSONObject(i);val status=r.getString("status");val c=col(18).apply{background=shape(Color.WHITE,16,true)};c.words(statuses[status]?:status,11f,purple,true);c.gap(5);c.words(r.getString("space"),20f,ink,true);c.gap(7);c.words(r.getString("date")+"  "+r.getString("time")+" · "+r.getInt("duration")+"분",13f);c.gap(7);c.words("요청자 "+r.optString("requesterName")+" · 추가 부담 한도 "+money(r.getInt("budget")),12f,muted)
   if(r.has("alternativeDate")){c.gap();c.words("이동 제안  "+r.getString("alternativeDate")+" "+r.getString("alternativeTime"),13f,purple,true);c.words("변경 보상 "+money(r.optInt("reward"))+" · 기본 이용료 "+money(r.optInt("basePrice")),12f,muted);c.words("응답 기한 "+stamp(r.optLong("expiresAt")),11f,muted)}
   val uid=user!!.getString("id");val requester=r.getString("requesterId")==uid;val recipient=r.optString("recipientId")==uid;val owner=user!!.optString("role")=="owner"
   if((status=="proposed"&&recipient)||(status=="accepted_a"&&requester))c.addView(button(if(recipient)"시간 이동 제안 수락"else"조건 확인하고 수락"){confirm("제안을 수락할까요?","제안 수락 이후에도 업체의 예약 시스템 확인이 필요해요."){action(r,"accept")}})
   if((status=="proposed"||status=="accepted_a")&&(requester||recipient))c.addView(button("제안 거절",false){confirm("제안을 거절할까요?","해당 제안의 진행이 종료됩니다."){action(r,"decline")}})
   if(owner&&status=="pending")c.addView(button("예약 변경 제안 만들기"){propose(r)})
   if(owner&&status=="accepted_b")c.addView(button("원래 예약 반영 확인"){confirmBooking(r)})
   if(requester&&status !in listOf("confirmed","cancelled","declined"))c.addView(button("요청 취소",false){confirm("요청을 취소할까요?","확정 전 희망 시간 요청을 취소합니다."){action(r,"cancel")}})
   if(status=="confirmed"){c.gap(8);c.words("업체 확인번호: "+r.optString("confirmationReference"),12f);c.words("결제 미연동 · 보상 미지급\n실제 이용 및 정산은 업체와 확인해주세요.",11f,muted)}
   c.addView(button("진행 기록 보기",false){task({api("/api/requests/"+r.getString("id")+"/events")}){j->val a=j.getJSONArray("events");val lines=(0 until a.length()).joinToString("\n\n"){n->val e=a.getJSONObject(n);(statuses[e.getString("action")]?:e.getString("action"))+" · "+stamp(e.getLong("created_at"))};AlertDialog.Builder(this).setTitle("진행 기록").setMessage(lines).setPositiveButton("닫기",null).show()}});content.addView(c);content.gap(14)
  }
 }
 private fun stamp(s:Long)=Instant.ofEpochSecond(s).atZone(ZoneId.systemDefault()).format(DateTimeFormatter.ofPattern("M/d HH:mm"))
 private fun account(){content.words("나의 PLYT",28f,ink,true);content.gap(14);if(user==null){content.words("좋은 시간의 시작, PLYT에 오신 걸 환영해요.",14f,muted);content.addView(button("로그인 / 회원가입"){auth()})}else{content.words(user!!.getString("name")+" 님",22f,ink,true);content.words(user!!.getString("email"),14f,muted);content.gap(6);content.words(if(user!!.getString("role")=="owner")"사장님 계정 · 예약 변경 관리"else"고객 계정 · 공간과 시간을 연결해요",13f,purple);content.addView(button("로그아웃",false){task({api("/api/auth/logout","POST",JSONObject())}){prefs.edit().remove("token").apply();user=null;requests=JSONArray();favorites.clear();shell()}})};content.gap(28);content.words("서비스 연결",18f,ink,true);content.gap(8);content.words("앱과 웹이 같은 서버를 사용하면 요청과 저장한 공간이 함께 이어집니다.",13f,muted);val address=edit("https://your-plyt-server.example",base(),17);content.addView(address);content.addView(button("서버 주소 저장 및 연결 확인",false){val value=address.text.toString().trim().trimEnd('/');try{val u=URL(value);if(u.protocol!="https"&&!(BuildConfig.DEBUG&&u.protocol=="http"))throw Exception();if(u.host.isNullOrBlank()||u.userInfo!=null||u.query!=null||u.ref!=null||u.path !in listOf("","/"))throw Exception();if(value!=base()){prefs.edit().putString("base",value).remove("token").apply();user=null;favorites.clear();requests=JSONArray()}else prefs.edit().putString("base",value).apply();refresh()}catch(e:Exception){toast("경로 없는 올바른 서버 주소를 입력해주세요.")}});if(BuildConfig.DEBUG){content.gap(8);content.words("개발용 APK · 에뮬레이터 기본 주소 10.0.2.2:8080\nUSB 기기는 adb reverse 연결 후 127.0.0.1:8080을 사용하세요.",11f,muted)};content.gap(28);content.words("현재 서비스 안내",18f,ink,true);content.gap(9);content.words("등록 공간은 예시입니다. 실사용 전 업체 입점과 예약 재고 확인이 필요해요.\n\n제안 수락과 예약 확정은 구분됩니다. 업체가 원래 예약 시스템 반영을 확인한 뒤 최종 상태가 변경돼요.\n\n외부 예약 API, 결제, 문자 알림, 보상 지급은 연결되지 않았어요. 새로고침하면 최신 상태를 불러와요.",13f,muted);content.gap(16);content.words("PLYT 0.1.0 · Native Android",11f,muted)}
 private fun confirm(title:String,message:String,yes:()->Unit){AlertDialog.Builder(this).setTitle(title).setMessage(message).setNegativeButton("돌아가기",null).setPositiveButton("확인"){_,_->yes()}.show()}
 private fun formDialog(title:String,form:LinearLayout,submit:String,fn:(AlertDialog)->Unit):AlertDialog{val scroll=ScrollView(this);scroll.addView(form);val d=AlertDialog.Builder(this).setTitle(title).setView(scroll).setNegativeButton("닫기",null).setPositiveButton(submit,null).create();d.setOnShowListener{d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener{if(!busy)fn(d)}};d.show();return d}
 private fun auth(register:Boolean=false){val f=col(22);f.words(if(register)"공간과 시간을 이어갈 계정을 만들어요."else"앱과 웹에서 같은 계정을 사용하세요.",13f,muted);val name=edit("이름");val email=edit("이메일",type=33);val pass=edit("비밀번호 (8자 이상)",type=129);if(register)f.addView(name);f.addView(email);f.addView(pass);val owner=CheckBox(this).apply{text="사장님 계정으로 처음 등록";textSize=12f};val setup=edit("서버의 사장님 등록 코드");setup.visibility=View.GONE;if(register){f.addView(owner);f.addView(setup);owner.setOnCheckedChangeListener{_,b->setup.visibility=if(b)View.VISIBLE else View.GONE};f.gap(10);f.words("이름, 이메일, 암호화된 비밀번호와 서비스 이용 기록이 연결한 서버에 저장돼요. 실제 예약·결제는 연결되지 않았어요.",11f,muted)};val toggle=button(if(register)"이미 계정이 있어요 → 로그인"else"처음 오셨나요? 회원가입",false){};f.addView(toggle);lateinit var d:AlertDialog;d=formDialog(if(register)"PLYT 회원가입"else"PLYT 로그인",f,if(register)"가입하기"else"로그인"){dlg->val j=JSONObject().put("email",email.text.toString().trim()).put("password",pass.text.toString());if(register)j.put("name",name.text.toString().trim()).put("owner",owner.isChecked).put("setupKey",setup.text.toString().trim());task({api(if(register)"/api/auth/register"else"/api/auth/login","POST",j)}){v->prefs.edit().putString("token",v.getString("token")).apply();user=v.getJSONObject("user");dlg.dismiss();shell();refresh()}};toggle.setOnClickListener{d.dismiss();auth(!register)}}
 private fun dateField(initial:String=LocalDate.now().plusDays(1).toString()):EditText{val e=edit("날짜",initial);e.isFocusable=false;e.setOnClickListener{val d=try{LocalDate.parse(e.text.toString())}catch(x:Exception){LocalDate.now().plusDays(1)};DatePickerDialog(this,{_,y,m,n->e.setText(String.format("%04d-%02d-%02d",y,m+1,n))},d.year,d.monthValue-1,d.dayOfMonth).apply{datePicker.minDate=System.currentTimeMillis()}.show()};return e}
 private fun spinner(v:List<String>,selected:Int=0)=Spinner(this).apply{adapter=ArrayAdapter(this@MainActivity,android.R.layout.simple_spinner_dropdown_item,v);setSelection(selected);layoutParams=LinearLayout.LayoutParams(-1,dp(50))}
 private fun times()=(18..42).map{String.format("%02d:%02d",it/2,it%2*30)}
 private fun createRequest(s:JSONObject){val f=col(22);f.words("희망 시간을 남기면 업체가 변경 가능성을 확인해요.",13f,muted);f.gap();f.words("희망 날짜",12f,ink,true);val date=dateField();f.addView(date);f.gap();f.words("시작 시간",12f,ink,true);val time=spinner(times(),10);f.addView(time);f.words("이용 시간",12f,ink,true);val duration=spinner(listOf("1시간","1시간 30분","2시간","2시간 30분","3시간","3시간 30분","4시간"),2);f.addView(duration);f.words("최대 추가 부담액",12f,ink,true);val budget=edit("0~100000원","20000",2);f.addView(budget);f.gap();f.words("기본 이용료와 별도이며, 요청만으로 결제·예약이 확정되지 않아요. 운영시간 09:00–22:00.",11f,muted);formDialog(s.getString("name"),f,"희망 시간 요청"){d->val n=budget.text.toString().toIntOrNull();if(n==null||n !in 0..100000){toast("추가 부담 한도는 0~100,000원이에요.");return@formDialog};val j=JSONObject().put("spaceId",s.getInt("id")).put("date",date.text.toString()).put("time",time.selectedItem.toString()).put("duration",60+duration.selectedItemPosition*30).put("budget",n);task({api("/api/requests","POST",j)}){d.dismiss();toast("희망 시간 요청을 접수했어요.");page="requests";refresh()}}}
 private fun action(r:JSONObject,a:String){task({api("/api/requests/"+r.getString("id")+"/action","POST",JSONObject().put("action",a))}){toast("진행 상태를 업데이트했어요.");refresh()}}
 private fun propose(r:JSONObject){val f=col(22);f.words("기존 예약과 대체 시간의 가용 여부를 먼저 확인하세요. 가입된 기존 예약자에게 앱·웹에서 제안이 표시돼요.",13f,muted);val email=edit("기존 예약자 가입 이메일",type=33);val ref=edit("기존 예약 확인번호");val date=dateField(r.getString("date"));val time=spinner(times(),12);val reward=edit("변경 보상 (고객 부담 한도 이하)",r.getInt("budget").toString(),2);f.addView(email);f.addView(ref);f.gap();f.words("이동할 대체 날짜와 시간",12f,ink,true);f.addView(date);f.addView(time);f.addView(reward);f.gap();f.words("응답 기한은 제안 후 48시간입니다. 문자 알림은 발송하지 않습니다.",11f,muted);formDialog("예약 변경 제안",f,"제안 등록"){d->val n=reward.text.toString().toIntOrNull();if(n==null){toast("보상 금액을 입력해주세요.");return@formDialog};val j=JSONObject().put("action","propose").put("recipientEmail",email.text.toString().trim()).put("bookingReference",ref.text.toString().trim()).put("alternativeDate",date.text.toString()).put("alternativeTime",time.selectedItem.toString()).put("reward",n);task({api("/api/requests/"+r.getString("id")+"/action","POST",j)}){d.dismiss();refresh()}}}
 private fun confirmBooking(r:JSONObject){val f=col(22);f.words("양측 수락을 확인했어요. 원래 예약 시스템에서 두 예약과 이용 시간을 반영한 뒤 확인번호를 남기세요.",13f,muted);val ref=edit("원래 예약 시스템 반영 확인번호");val check=CheckBox(this).apply{text="원래 예약 시스템 반영을 직접 확인했습니다.";textSize=12f};f.addView(ref);f.addView(check);f.gap();f.words("이 확인으로 결제나 보상 지급이 발생하지 않아요. 결제·정산은 별도 확인이 필요합니다.",11f,muted);formDialog("업체 최종 확인",f,"반영 확인 완료"){d->if(!check.isChecked){toast("원래 예약 반영을 먼저 확인해주세요.");return@formDialog};val j=JSONObject().put("action","confirm").put("originalSystemUpdated",true).put("confirmationReference",ref.text.toString().trim());task({api("/api/requests/"+r.getString("id")+"/action","POST",j)}){d.dismiss();refresh()}}}
 private inner class SpaceArt(context:Context,private val variant:Int):View(context){private val p=Paint(Paint.ANTI_ALIAS_FLAG);override fun onDraw(c:Canvas){super.onDraw(c);val w=width.toFloat();val h=height.toFloat();p.shader=LinearGradient(0f,0f,w,h,intArrayOf(if(variant==3)0xffb9b8c4.toInt()else 0xffe8ddce.toInt(),if(variant==2)0xffc0c7b5.toInt()else 0xffd3c8be.toInt()),null,Shader.TileMode.CLAMP);c.drawRect(0f,0f,w,h,p);p.shader=null;p.color=0xfff8f4e8.toInt();c.drawRoundRect(w*.11f,h*.13f,w*.49f,h*.69f,12f,12f,p);p.color=0xffdfd8c7.toInt();c.drawRect(w*.285f,h*.13f,w*.3f,h*.69f,p);c.drawRect(w*.11f,h*.39f,w*.49f,h*.405f,p);p.color=0xff9a8e85.toInt();c.drawRect(0f,h*.79f,w,h,p);p.color=if(variant==3)0xff696273.toInt()else 0xffa49c88.toInt();c.drawRoundRect(w*.51f,h*.53f,w*.86f,h*.84f,20f,20f,p);p.color=0xffede5d4.toInt();c.drawRoundRect(w*.55f,h*.49f,w*.82f,h*.7f,16f,16f,p);p.color=0xff5f7656.toInt();c.drawOval(w*.83f,h*.18f,w*.94f,h*.57f,p);p.color=0xffb98f70.toInt();c.drawRoundRect(w*.85f,h*.51f,w*.93f,h*.82f,6f,6f,p);p.color=0x99713de8.toInt();p.textSize=dp(11).toFloat();p.typeface=Typeface.create("sans-serif-medium",Typeface.NORMAL);c.drawText("PLYT / SPACE "+String.format("%02d",variant),dp(18).toFloat(),h-dp(15),p)}}
}
